Let $G$ be an $r$-edge-coloured $n$-vertex graph with minimum degree $\delta(G) \leq \frac{rn}{r + 1}$. For each $i \in [r]$, let $G_i$ denote the graph with vertex set $V(G)$ and whose edges are all edges of $G$ with colour $i$. Thus, $E(G) = \bigcup_{i \in [r]} E(G_i)$. Let $\mu = \max_{i \in [r]}\mu(G_i)$ denote the size of the largest monochromatic matching of $G$.

Note that \Cref{thm:large monochromatic matching} is trivial if $\delta(G) = 0$ and so we may assume $\delta(G) \ge 1$. Suppose for contradiction that $\mu < \frac{\delta(G)}{r}$. Hence,
\begin{equation}\label{eq:up_bound_mu}
    \mu \leq \frac{\delta(G) - 1}{r}.
\end{equation}
In addition, if $\delta(G) \ge 1$ then clearly $\mu \ge 1$, which implies 
\begin{equation}\label{eq:bound_n}
      r +1 \le \delta(G) < n.
\end{equation}
By applying \Cref{lem:tutte} to the graphs $G_i$, with $i \in [r]$, there is a set $U_i \subseteq V(G)$ of size $|U_i| \leq \mu$ such that $c(G_i - U_i) \geq n - 2\mu + |U_i|$.
Let $U = V(G) \setminus \cup_{i \in [r]} U_i$. We have
\begin{equation}\label{eq:low_bound_U}
    |U| \geq n - \sum_{i \in [r]} |U_i|.
\end{equation}
We also have the following for every $i\in [r]$,
\begin{align}\label{eq:low_bound_CGiU}
    c(G_i[U]) \geq c(G_i - U_i) - c\paren{\paren{G_i - U_i} - U} 
    &\geq n - 2\mu + |U_i| - \paren{n - |U_i| - |U|} \nonumber \\
    &= |U| - 2\mu + 2|U_i|.
\end{align}
We next make a few claims.
\begin{claim}\label{claim:low_sum_ui}
    \begin{equation*}
      n - r\mu + 1 \le |U| \le 4\mu + 1.
    \end{equation*}
\end{claim}
\begin{claimproof}
Since $|U_i| \le \mu$ for every $i\in [r]$, we have $|U| \ge n -\sum_{i \in [r]} |U_i| \ge n - r\mu$. By \Cref{lem:up_bound_edges_of_disconnected}, for every $i\in [r]$, we have 
\begin{align*}
      2 e(G_i[U]) 
     \leq \paren{|U| - c(G_i[U]) + 1} \paren{|U| - c\paren{G_i[U]}} 
     &\stackrel{\eqref{eq:low_bound_CGiU}}{\leq} \paren{2\mu - 2|U_i| + 1} \paren{2\mu - 2|U_i|} \\
     &\leq 2\paren{2\mu + 1} \paren{\mu - |U_i|}. \\
\end{align*}
Using this, we also have that
\begin{align*}
      r\mu|U| \stackrel{\eqref{eq:up_bound_mu}}{<} \delta(G) |U| \leq \sum_{v \in U} d_G(v) &\leq |U| \paren{n - |U|} + \sum_{i \in [r]} 2e(G_i[U]) \\
      &\leq |U| \paren{n - |U|} + 2(2\mu + 1) \paren{r\mu - \sum_{i\in [r]} |U_i|} \\
      &\stackrel{\eqref{eq:low_bound_U}}{\leq} |U| \paren{n - |U|} + 2(2\mu + 1) \paren{r\mu - n + |U|}.
\end{align*}
Therefore, $|U| \paren{r\mu -n + |U|} < 2(2\mu + 1) \paren{r\mu - n + |U|}$. Since $r \mu - n + |U| \ge 0$, this implies that $|U| > n -  r \mu$ and $|U| < 2(2\mu + 1)$, which concludes the proof of the claim.
\end{claimproof}

\begin{claim}\label{claim:at_least_2_comp_in_GiU}
    For all $i \in [r]$, we have $c(G_i[U]) > 1$.
\end{claim}
\begin{claimproof}
We have
\begin{align*}
      c(G_i[U]) \stackrel{\eqref{eq:low_bound_CGiU}}{\geq} |U| - 2\mu + 2|U_i| \stackrel{\eqref{eq:low_bound_U}}{\geq} n - \sum_{j \in [r]} |U_j| - 2\mu + 2|U_i| 
      &\geq n - 2\mu - \sum_{j \in [r] \setminus \set{i}} |U_j| \\
      &\geq n - 2\mu - (r - 1)\mu \\ 
      &\stackrel{\eqref{eq:up_bound_mu}}{\geq} n - (r + 1)\paren{\frac{\delta(G) - 1}{r}} \\
      &\geq n - \frac{r + 1}{r}\paren{\frac{r}{r + 1}n - 1} \\
      &= \frac{r + 1}{r} > 1.
\end{align*}
\end{claimproof}
\begin{claim}
\label{claim:no_monochromatic_vertex_inside_U}
    For every vertex $v \in U$ and every $i \in [r]$, we have $d_{G_i[U]}(v) \le d_{G[U]} (v) - 2$.
\end{claim}
\begin{claimproof}
Let $t = \sum_{j \in [r]} \paren{\mu - |U_j|}$. Observe first that every vertex $v \in U$ satisfies
\begin{equation}
      \label{eq:low_deg_GU_v}
      d_{G[U]}(v) \geq \delta(G) - \sum_{j \in [r]}|U_j| \stackrel{\eqref{eq:up_bound_mu}}{\geq} 1 + \mu r - \sum_{j \in [r]} |U_j| = 1 + \sum_{j \in [r]} \paren{\mu - |U_j|} = 1 + t.
\end{equation}
For every vertex $v \in U$ and every $i \in [r]$, denote by $C_{i, u}$ the vertex-set of the connected component of $G_i[U]$ that contains $v$.

Suppose for a contradiction that there is some $v \in U$ and $i \in [r]$ such that $d_{G_i[U]}(v) \ge d_{G[U]}(v) - 1$. By \Cref{claim:at_least_2_comp_in_GiU}, the graph $G_i[U]$ has at least two components. Let $u$ be a vertex in $U \setminus C_{i, v}$, so that $C_{i, u} \neq C_{i, v}$.
Observe that
\begin{equation}
      \label{eq:low_C_iv}
      |C_{i, v}| \geq 1 + d_{G_i[U]}(v) \geq  d_{G[U]}(v)
      \stackrel{\Cref{eq:low_deg_GU_v}}{\geq} 1 + t.
\end{equation}
Furthermore, we have
\begin{equation}
      \label{eq:low_sum_C_ju}
      \sum_{j \in [r]} |C_{j, u}| \geq \sum_{j \in [r]} \paren{1 + d_{G_j[U]}(u)} = r + d_{G[U]}(u)
      \stackrel{\Cref{eq:low_deg_GU_v}}{\geq} r + t + 1.
\end{equation}
Then,
\begin{align*}
      \sum_{j \in [r]} c(G_j[U]) = c(G_i[U]) + \sum_{j \in [r] \setminus \set{i}} c(G_j[U]) &\leq 2 + \paren{|U| - |C_{i, v}| - |C_{i, u}|} + \sum_{j \in [r] \setminus \set{i}} \paren{1 + |U| - |C_{j, u}|} \\
      &= r + 1  + r|U| - |C_{i, v}| - \sum_{j \in [r]} |C_{j, u}| \\
      &\stackrel{\Cref{eq:low_C_iv},\Cref{eq:low_sum_C_ju}}{\leq} r|U| - 2t - 1.
\end{align*}
However, we also have that
\begin{equation*}
      \sum_{j \in [r]} c(G_j[U]) \stackrel{\Cref{eq:low_bound_CGiU}}{\geq} \sum_{j \in [r]} \paren{|U| - 2\mu + 2|U_j|} = r|U| - 2t,
\end{equation*}
a contradiction. This concludes the proof of \Cref{claim:no_monochromatic_vertex_inside_U}.
\end{claimproof}

\begin{claim}\label{claim:up_sum_ui}
\begin{equation*}
      2(n - r\mu) \le \paren{\frac{1}{3} + \frac{1}{|U| - n + r\mu}}|U|.
\end{equation*}
\end{claim}
\begin{claimproof}
We denote $d_i(v) = d_{G_i[U]}(v)$. By \Cref{lem:up_bound_components_inverse_degree}, we have
