\label{thm:clean-up_main}
   Let $r\ge 2$, $C\ge 0$, $\eps \in (0,\frac{1}{2}]$, and $\alpha \in \left[\frac{1}{2} + \frac{1}{2r}, 1\right]$.
   Then there exists $\delta >0$ such that the random graph $G \sim G(n,p)$ with $p \ge \frac{\log{n}}{2n}$ satisfies the following with probability $1-o(n^{-3})$.
   Let $H$ be an $\alpha$-residual spanning subgraph of $G$ such that the following hold. 
   \begin{enumerate}[leftmargin=*,label = {\bfseries A\arabic{enumi}}]
   \item Every vertex $v\in V(H)$ satisfies $d_H(v)\ge 2$.
   \label{item:mindeg2}
   \item No two vertices $u,v\in V(H)$ satisfying $d_H(u),d_H(v)\le \frac{np}{5000}$ are within distance $5$ from each other.
   \label{item:property low_deg_vertices_far_apart}
   \end{enumerate}
   Let $\mathcal{P}$ be a linear forest in $H$ spanning a vertex set $S$ where ${|S| = (1-\eps) \min\Set{(2\alpha - 1)n, \frac{2\alpha n}{r}, \frac{2n}{r+1}}}$. Suppose $\mathcal{P}$ contains at most $C$ paths.
   Then, there exists a set $T \supseteq S$ and a linear forest $\mathcal{P}^*$ in $H$ covering $T$ such that, setting $U = V(H)\setminus T$, the following conditions hold.

   \begin{enumerate}[leftmargin=*,label = {\bfseries B\arabic{enumi}}]
   \item $d_{H}\left(u,U\right) \ge \max\left(\frac{p|U|}{5000}, \; \left(\frac{1}{2}+\delta\right)d_{G}\left(u,U\right)\right)$ for all $u \in U$.
   \label{eq:degree_in_U}
   \item $|U| \ge n - |S| - \frac{300r}{\delta^2 p}$.
   \label{eq:size_of_U}    
   \item All but at most $\frac{2000r}{\delta^2 p}$ edges of $\mathcal{P}$ are included in $\mathcal{P}^*$.\label{eq:most_of_path_used}
   \item There are at most $\frac{2000r}{\delta^2 p}$ paths in $\mathcal{P}^*$.
   \label{eq:number_of_paths}
   \item All paths in $\mathcal{P}^*$ have at least $3$ vertices, with endpoints lying in $U$ and all other vertices lying in~$T$. \label{eq:matching}
   \item If $W$ is the set of all endpoints of paths in $\mathcal{P}^*$, then $d_H(u, W) \le (np)^{1/5}$ for all $u \in U$.
   \label{eq:deg_U_to_M}
   \end{enumerate}

