\begin{lemma}\label{lem:Hall_to_extend_paths}
    Let $H$ be a graph, and let $A$ and $T$ be sets such that $A\subseteq T\subseteq V(H)$ and \ref{item:Hall's condition} holds. Let $\mathcal{P}_1$ be a linear forest in $H$ spanning $A$.
    Then, there exists a linear forest $\mathcal{P}_2$ in $H$ spanning $T$ such that the following hold.
    \begin{enumerate}[leftmargin=*,label = {\bfseries D\arabic{enumi}}]
        \item The endpoints of all paths in $\mathcal{P}_2$ lie in $A$. \label{eq:endpoints_in_R}
        \item All but at most $4|T \setminus A|$ edges of $\mathcal{P}_1$ are used in $\mathcal{P}_2$.
        \label{item:few edges left}
        \item The number of paths in $\mathcal{P}_2$ minus the number of paths in $\mathcal{P}_1$ is at most $3|T\setminus A|$.
        \label{item:few paths added}
    \end{enumerate}
\end{lemma}
We now use these lemmas to conclude the proof of \Cref{thm:clean-up_main}. Recall that $\mathcal{P}[S \setminus (K \cup K')]$ denotes the subgraph of $\mathcal{P}$ induced by $S \setminus (K \cup K')$. Since $\mathcal{P}$ is a linear forest, $\mathcal{P}[S \setminus (K \cup K')]$ is also a linear forest. Then let $\mathcal{P}_0$ be the linear forest formed by taking the union of $\mathcal{P}[S \setminus (K \cup K')]$ and all the paths of $\{P_v:v\in K\}$. Note that $\mathcal{P}_0$ spans $S \cup K \cup K'$.

Take $A$ and $T$ with $A\subseteq S\cup K \cup K'\subseteq T$ as given by \Cref{lem:combined}. We will next construct a linear forest $\mathcal{P}_2$ spanning $T$, ensuring that the endpoints of the paths in $\mathcal{P}_2$ lie in $A$. This will allow us to extend to a desired linear forest $\mathcal{P}^*$ using \ref{item:degree_in_unused_part}. For this, let $\mathcal{P}_1$ be the subgraph of $\mathcal{P}_0$ induced by $A$. Since $\mathcal{P}_0$ is a linear forest, $\mathcal{P}_1$ is also a linear forest.
Finally, let $\mathcal{P}_2$ be the linear forest spanning $T$ given by~\Cref{lem:Hall_to_extend_paths} applied to the linear forest $\mathcal{P}_1$. 
Note that \ref{eq:degree_in_U} follows directly from \ref{item:degree_in_unused_part}.

We have
\begin{align*}
    |U| = n - |T| = n - |A| - |T\setminus A| \ge n - |S \cup K \cup K'| - |T\setminus A|
    &\ge n - |S| - 3|K| - |T\setminus A| \\
    &\ge n - |S| - \frac{300r}{\delta^2 p},
\end{align*}
where in the final step we have used \ref{item:property K small} and \ref{item:size_SminusA}. This proves~\ref{eq:size_of_U}.

By construction, the number of edges in $\mathcal{P}$ not in $\mathcal{P}_0$ is at most $2|K \cup K'|\le 6|K|$. Similarly, the number of edges in $\mathcal{P}_0$ not in $\mathcal{P}_1$ is at most $2|(S\cup K \cup K')\setminus A|$. By \ref{item:few edges left}, the number of edges in $\mathcal{P}_1$ not in $\mathcal{P}_2$ is at most $4|T\setminus A|$. Thus, the number of edges in $\mathcal{P}$ not in $\mathcal{P}_2$ is at most 
\[
6|K| + 2|(S\cup K \cup K')\setminus A| + 4|T\setminus A|\le 6|K| + 6|T\setminus A|\le \frac{2000r}{\delta^2 p},
\]
where the last inequality uses \ref{item:property K small} and \ref{item:size_SminusA}. This proves \ref{eq:most_of_path_used} for $\mathcal{P}_2$ (in place of $\mathcal{P}^*$). 

The number of paths in $\mathcal{P}[S \setminus (K \cup K')]$ is at most $|K| + |K'| = 3|K|$ more than the number of paths in $\mathcal{P}$. Thus the number of paths in $\mathcal{P}_0$ minus the number of paths in $\mathcal{P}$ is at most $3|K|+|K| = 4|K|$.
By construction, the number of paths in $\mathcal{P}_1$ minus the number of paths in $\mathcal{P}_0$ is at most $|(S\cup K \cup K')\setminus A|$. By \ref{item:few paths added}, the number of paths in $\mathcal{P}_2$ minus the number of paths in $\mathcal{P}_1$ is at most $3|T\setminus A|$. By assumption, the number of paths in $\mathcal{P}$ is at most $C \le \frac{200r}{\delta^2 p}$, where this inequality follows from the assumptions in \ref{item:parameter hierarchy}. Thus, the number of paths in $\mathcal{P}_2$ is at most 
\[
4|K| + |(S\cup K \cup K')\setminus A| + 3|T\setminus A| + \frac{200r}{\delta^2 p}\le 4|K| + 4|T\setminus A| + \frac{200r}{\delta^2 p}\le \frac{1000r}{\delta^2 p},
\]
where the last inequality uses \ref{item:property K small} and \ref{item:size_SminusA}.
This proves \ref{eq:number_of_paths} for $\mathcal{P}_2$ (in place of $\mathcal{P}^*$). 

Note that 
\begin{equation}\label{eq:lower bound on U}
    |U|\ge n-|S|-|T\setminus A| \;\overset{\text{\ref{item:size_SminusA}}}{\ge}\; n-\frac{2n}{r+1} -\frac{200r}{\delta^2 p}
    \quad\overset{\text{\ref{item:parameter hierarchy}}}{\ge} \quad\frac{n}{4}. 
\end{equation}
Let $Z$ be the set of endpoints of paths in $\mathcal{P}_2$, noting that $|Z| \le \frac{2000r}{\delta^2p}$. By \ref{eq:endpoints_in_R}, we have $Z \subseteq A$. Thus, by \ref{item:degree_in_unused_part}, each vertex $v \in U\cup Z$ satisfies $d_H(v,U) \ge \frac{p|U|}{5000} \ge \delta np$, where the last inequality uses \eqref{eq:lower bound on U} and \ref{item:parameter hierarchy}. By \ref{item:property 1}, for every $v\in V(H)$, we have $d_H(v,U) \le d_G(v) \le 10np$. Combining the last two inequalities, we get 
\begin{equation}\label{eq:bounds on degree to U}
    \delta np \le d_H(v,U) \le 10np \quad \text{ for every }  v \in U\cup Z.
\end{equation}

For every path $P$ in $\mathcal{P}_2$ with distinct endpoints $z_1,z_2\in Z$, we now wish to find two edges $z_1w_1, z_2w_2\in E(H)$ with $w_, w_2\in U$ so that appending these edges can extend $P$ to a path with endpoints in $U$. Although this will help us establish \ref{eq:matching}, we need to keep a few things in mind. First, we need to simultaneously ensure that \ref{eq:deg_U_to_M} holds. Second, in order for \ref{eq:matching} to hold, for any $z \in Z$ that is the only vertex of its path in $\mathcal{P}_2$, we will need two edges from $z$ to $U$ so that the path can be extended to have both endpoints in $U$. Third, all vertices in $U$ used to extend different paths in $\mathcal{P}_2$ must be distinct. This motivates us to construct two matchings $\mathcal{M}_1, \mathcal{M}_2$ between $Z$ and $U$ such that $\mathcal{M}_1, \mathcal{M}_2$ cover $Z$ and the sets $V(\mathcal{M}_1)\cap U$ and $V(\mathcal{M}_2)\cap U$ are disjoint. If we can do so, then we will construct a desired linear forest $\mathcal{P}^*$ from $\mathcal{P}_2$ in the following way. Consider the edge set $E\subseteq E(\mathcal{M}_1)$ formed by taking all edges in $\mathcal{M}_1$ incident to the vertices $z\in Z$ that are the only vertex of its path in $\mathcal{P}_2$. We now define $\mathcal{P}^*$ to be the graph obtained from adding the edges in $E\cup E(\mathcal{M}_2)$ to the linear forest $\mathcal{P}_2$. By construction, $\mathcal{P}^*$ is a linear forest and satisfies \ref{eq:matching}.
Moreover, note that as \ref{eq:most_of_path_used} and \ref{eq:number_of_paths} hold for $\mathcal{P}_2$, they will also hold for $\mathcal{P}^*$. We still need to ensure \ref{eq:deg_U_to_M}.

To this end, we will use the Lov\'asz Local Lemma to find a set $W'\subseteq U$ so that \ref{eq:deg_U_to_M} holds for $W'$ (in place of $W)$. We will then construct the matchings $\mathcal{M}_1, \mathcal{M}_2$ between $Z$ and $W'$ with the properties discussed in the last paragraph. This will ensure \ref{eq:deg_U_to_M}. Fix $q \coloneqq (np)^{-5/6}$. Select a random set $W' \subseteq U$ by including each vertex of $U$ independently with probability $q$. For every $v\in U\cup Z$, let $B_v$ denote the event that it does not hold that $d_H(v,W') = (1\pm \frac{1}{2})qd_H(v,U)$. Clearly, for every $v\in V(H)$, the random variable $d_H(v,W')$ is distributed as $\bin(d_H(v,U),q)$. Thus, we have $\Expect(d_H(v,W'))= qd_H(v,U)\ge \delta (np)^{1/6} $,  where the last inequality uses \eqref{eq:bounds on degree to U}. Therefore, by Chernoff's bound, for every $v\in U\cup Z$, we have the following.
\begin{align*}
    \Prob{B_v} \le 2\exp\left(-\frac{\Expect(d_H(v,W'))}{12}\right) \le 2\exp\left(-\frac{\delta(np)^{1/6}}{12}\right) \le (np)^{-3},
\end{align*}
where the last inequality uses the facts that $np \ge \frac{\log{n}}{2}$ and $n$ is sufficiently large relative to $\delta$.

Let $\mathcal{B} = \{B_v : v \in U \cup Z\}$. Observe that if two distinct vertices $u,v$ have no common neighbours in $H$ then the events $B_u$ and $B_v$ are independent. In particular, $B_u$ and $B_v$ are \emph{not} independent only if $u$ and $v$ are at most distance $2$ apart. By \ref{item:property 1}, for every vertex $v$, the number of vertices at distance at most $2$ from $v$ is at most $(10np)^2$. Thus, each event in $\mathcal{B}$ is independent from all but at most $(10np)^2$ others. 

We now apply \Cref{lem:LLL} with $\mathcal{B} = \{B_v : v \in U \cup Z\}$, $p = (np)^{-3}$, and $d = \left(10np\right)^2$. As $ep(d+1)<1$, there is a positive probability that no event in $\mathcal{B}$ occurs. In particular, this means that there must exist some set $W' \subseteq U$ such that 
\[
\text{every vertex} \;\; u \in U \;\; \text{satisfies} \;\; d_H(u,W') \le \frac{3}{2} q d_H(u,U) \overset{\eqref{eq:bounds on degree to U}}{\le} 15(np)^{1/6} \overset{\text{\ref{item:parameter hierarchy}}}{\le} (np)^{1/5}
\]
\[
\text{and every vertex} \;\; z \in Z \;\; \text{satisfies} \;\; d_H(z,W') \ge \frac{1}{2} q d_H(z,U) \overset{\eqref{eq:bounds on degree to U}}{\ge} \frac{\delta}{2}(np)^{1/6}.
\]
Fix such a set $W'$. This $W'$ clearly satisfies \ref{eq:deg_U_to_M}. To finish the proof, we will use \Cref{thm:Hall_variant} on the bipartite subgraph of $H$ induced by $Z,W'$ to obtain the matchings $\mathcal{M}_1, \mathcal{M}_2$ between $Z$ and $W'$ with the desired properties as described before. 
We will check Hall's condition that for all $Z' \subseteq Z$, we have $|N_H(Z') \cap W'| \ge 2|Z'|$. Suppose, for contradiction, this does not hold for some non-empty $Z'$. We know that $d_H(z,W') \ge \frac{\delta}{2}(np)^{1/6}$ for all $z \in Z$ and so
\begin{equation}\label{eq:lower bound on edges in Z' and its neighbor}
e_H(Z',N_H(Z')\cap W') \ge \sum_{z \in Z'} d_H(z,W') \ge \frac{\delta}{2}|Z'|(np)^{1/6}.
\end{equation}
Now, since $|N_H(Z') \cap W'| < 2|Z'|$, we have 
$|Z' \cup \left(N_H(Z') \cap W'\right)| < 3|Z'| \le 3|Z| \le \frac{6000r}{\delta^2 p}$. 
Thus, applying \ref{item:property 3} with $S=Z' \cup \left(N(Z') \cap W'\right)$, we have 
\[
e_H(Z',N(Z')\cap W') \le e_G(Z' \cup \left(N(Z') \cap W'\right)) \overset{\text{\ref{item:property 3}}}{\le} 3|Z'|(np)^{1/8},
\]
which contradicts \eqref{eq:lower bound on edges in Z' and its neighbor} because $np\ge \frac{\log{n}}{2}$ and $n$ is sufficiently large relative to $\delta$. Thus, Hall's condition holds, and we can apply~\Cref{thm:Hall_variant} to find the two matchings $\mathcal{M}_1, \mathcal{M}_2$ as required. 

If we denote by $W$ the set of all endpoints of paths in $\mathcal{P}^*$, then we have $W\subseteq W'$. Thus, it is now easy to see that as \ref{eq:deg_U_to_M} holds for $W'$, it also holds for $W$. This finishes the proof of \Cref{thm:clean-up_main}.

\label{lem:combined}
Let $r,C,\eps,\alpha,\delta,n,p$ be as in \ref{item:parameter hierarchy}.
Let $G$ be an $n$-vertex graph satisfying \ref{item:property 2 both}--\ref{item:property 3}, and let $H$ be an $\alpha$-residual spanning subgraph of $G$ satisfying \ref{item:mindeg2}--\ref{item:property of K'}. Let $K$ and $K'$ be as in \ref{item:property K small} and \ref{item:property of K'}.
Let $S \subseteq V(H)$ be such that $|S| = (1-\eps) \min\Set{(2\alpha - 1)n, \frac{2\alpha n}{r}, \frac{2n}{r+1}}$.
Then, there exist sets $A$ and $T$ with $A\subseteq S \cup K \cup K' \subseteq T$ such that, setting $U = V(H)\setminus T$, the following hold. 
\begin{enumerate}[leftmargin=*,label = {\bfseries C\arabic{enumi}}]
    \item
    $d_{H}\left(u,U\right) \ge \max\left(\frac{p|U|}{5000}, \; \left(\frac{1}{2}+\delta\right)d_{G}\left(u,U\right)\right)$ for all $u \in U\cup A$. 
   \label{item:degree_in_unused_part}
    \item $|T\setminus A| \le \frac{200r}{\delta^2 p}.$ 
    \label{item:size_SminusA}
    \item There exists an ordering $y_1,y_2,y_3,\ldots $ on $T \setminus A$ such that for all sets $Z \subseteq T \setminus A$,
    \[\left|\bigcup_{y_i \in Z} (N_H(y_i) \cap (A \cup \{y_1,y_2,\ldots,y_{i-1}\}))\right| \ge 2|Z|.\] \label{item:Hall's condition}
\end{enumerate}

\label{lem:Hall_to_extend_paths}
    Let $H$ be a graph, and let $A$ and $T$ be sets such that $A\subseteq T\subseteq V(H)$ and \ref{item:Hall's condition} holds. Let $\mathcal{P}_1$ be a linear forest in $H$ spanning $A$.
    Then, there exists a linear forest $\mathcal{P}_2$ in $H$ spanning $T$ such that the following hold.
    \begin{enumerate}[leftmargin=*,label = {\bfseries D\arabic{enumi}}]
        \item The endpoints of all paths in $\mathcal{P}_2$ lie in $A$. \label{eq:endpoints_in_R}
        \item All but at most $4|T \setminus A|$ edges of $\mathcal{P}_1$ are used in $\mathcal{P}_2$.
        \label{item:few edges left}
        \item The number of paths in $\mathcal{P}_2$ minus the number of paths in $\mathcal{P}_1$ is at most $3|T\setminus A|$.
        \label{item:few paths added}
    \end{enumerate}

\begin{align*}
    |U| = n - |T| = n - |A| - |T\setminus A| \ge n - |S \cup K \cup K'| - |T\setminus A|
    &\ge n - |S| - 3|K| - |T\setminus A| \\
    &\ge n - |S| - \frac{300r}{\delta^2 p},
\end{align*}

\begin{equation}\label{eq:lower bound on U}
    |U|\ge n-|S|-|T\setminus A| \;\overset{\text{\ref{item:size_SminusA}}}{\ge}\; n-\frac{2n}{r+1} -\frac{200r}{\delta^2 p}
    \quad\overset{\text{\ref{item:parameter hierarchy}}}{\ge} \quad\frac{n}{4}. 
\end{equation}

\begin{equation}\label{eq:bounds on degree to U}
    \delta np \le d_H(v,U) \le 10np \quad \text{ for every }  v \in U\cup Z.
\end{equation}

\begin{align*}
    \Prob{B_v} \le 2\exp\left(-\frac{\Expect(d_H(v,W'))}{12}\right) \le 2\exp\left(-\frac{\delta(np)^{1/6}}{12}\right) \le (np)^{-3},
\end{align*}

\[
\text{every vertex} \;\; u \in U \;\; \text{satisfies} \;\; d_H(u,W') \le \frac{3}{2} q d_H(u,U) \overset{\eqref{eq:bounds on degree to U}}{\le} 15(np)^{1/6} \overset{\text{\ref{item:parameter hierarchy}}}{\le} (np)^{1/5}
\]

\begin{equation}\label{eq:lower bound on edges in Z' and its neighbor}
e_H(Z',N_H(Z')\cap W') \ge \sum_{z \in Z'} d_H(z,W') \ge \frac{\delta}{2}|Z'|(np)^{1/6}.
\end{equation}

In this proof, let $V=V(H)$, and for a set $Y\subseteq V$, we write $\overline{Y}$ to denote $V\setminus Y$.

Let $S' = S \cup K \cup K'$.
We define a sequence of sets as follows. Let $S_0=S'$ and for all $i \ge 0$ do the following:
 if there exists some vertex $v \not\in S_i$ such that $d_H(v,\overline{S_i}) < \max\set{\frac{p|\overline{S_i}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(v,\overline{S_i})}$, set $x_{i+1}$ to be such a vertex and let $S_{i+1}= S_i \cup \{x_{i+1}\}$. 
Otherwise, if there are no such vertices, set $T=S_i$ and end the process. 


Let $\ell = |T\setminus S'|$ denote the number of steps in this process before it ends, so in particular $T=S_{\ell}$. Let $U = \overline{T}$. By construction we have $d_H\left(u,U\right) \ge \max\set{\frac{p|U|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(u,U)}$ for all $u \in U$ and so \ref{item:degree_in_unused_part} holds for vertices in $U$.
Let $A \coloneqq \{v \in S' : d_H(v,U) \ge \max\set{\frac{p|U|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(v,U)}\}$. Then \ref{item:degree_in_unused_part} also holds for vertices in $A$.

Next, we will show that \ref{item:size_SminusA} holds. By definition of $A$, we see that for every $y \in S' \setminus A$ we have 
\[
d_H(y,U) < \max\left\{\frac{p|U|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(y,U)\right\} \le \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})\right\}
\]
and thus,
\begin{equation}\label{eq:S minus A has high edges in T}
d_H(y,T) = d_H(y) - d_H(y,U) > d_H(y) - \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})\right\}.
\end{equation}
For every $i \in [\ell]$, using how the set $S_i$ was constructed, we have 
\[d_H(x_i,\overline{S_{i-1}}) < \max\left\{\frac{p|\overline{S_{i-1}}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(x_i,\overline{S_{i-1}})\right\} \le \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(x_i,\overline{S})\right\}
\]
and thus,
\begin{equation}\label{eq:T minus S has high edges in S}
d_H(x_i,T) \ge d_H(x_i,S_{i-1}) = d_H(x_i) - d_H(x_i,\overline{S_{i-1}}) 
> d_H(x_i) - \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(x_i,\overline{S})\right\}.
\end{equation}
In particular, by~\eqref{eq:S minus A has high edges in T} and~\eqref{eq:T minus S has high edges in S}, we see that for all $y \in T \setminus A$, we have
\begin{equation}\label{eq:T minus A has high edges in T}
d_H(y,T) > d_H(y) - \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})\right\} \ge \alpha d_G(y) - \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})\right\}.
\end{equation}
Recall that $\ell = |T\setminus S'|$. Let $k = \min\set{\ell,\frac{200r}{\delta^2 p}}$. Define the set 
\[
Z =
\begin{cases*} 
\{x_1,\dots,x_k\}, & if $k< \ell$
\\T\setminus A, & otherwise.
\end{cases*}
\]
For every $i\in [k]$, we have $d_G(x_i,S_k)\ge d_G(x_i,S_{i-1})\ge d_H(x_i,S_{i-1})$ and for every $y\in T\setminus A$, we have $d_G(y,S_{\ell})= d_G(y,T)\ge d_H(y,T)$. 
Thus, using \eqref{eq:T minus S has high edges in S}, \eqref{eq:T minus A has high edges in T}, and the definition of $Z$, we have the following (for both the cases $k< \ell$ and $k=\ell$).
\[
e_G(Z,S_k) = \sum_{y \in Z} d_G(y,S_k) > \sum_{y \in Z}\left(\alpha d_G(y) - \max\left\{\frac{p|\overline{S}|}{5000}, \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})\right\}\right).
\]
Define $L \coloneqq \left\{y \in V: \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})< \frac{p|\overline{S}|}{5000}\right\}$.
Then we have 
\begin{align}
    e_G(Z,S_k) &> \sum_{y \in Z}\alpha d_G(y) - \sum_{y \in Z \setminus L} \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S}) - \sum_{y \in L\cap Z}\frac{p|\overline{S}|}{5000} \nonumber\\
    &= \alpha e_G(Z,V)  - \left(\tfrac{1}{2}+\delta\right)e_G(Z\setminus L,\overline{S}) - \frac{p|L\cap Z||\overline{S}|}{5000} \label{eq:T minus A to S lower bound}
\end{align}
Assume for contradiction that $|T\setminus A| > \frac{200r}{\delta^2 p}$.  Then, $|Z|\ge \frac{200r}{\delta^2 p}$ and so $p|Z|n >  \frac{100n}{\delta^2}$. In particular, by~\ref{item:property 2}, we have
\begin{equation}\label{eqn:bound_Z_V}
    e_G(Z,V) \ge (1-\delta)p|Z|n.
\end{equation}
Note that $e_G(L,\overline{S}) < \frac{p|L||\overline{S}|}{\left(\tfrac{1}{2}+\delta\right)5000} < \frac{p|L||\overline{S}|}{2500}$ and therefore, by \ref{item:property 2 alt version}, we must have $p|L||\overline{S}| <  150n$. Since $|\overline{S}| = n-|S| \ge \left(1-\frac{2}{r+1}\right)n \ge \frac{n}{3}$, we get in particular that $|L| \le \frac{450}{p}$. 
Thus, $|Z \setminus L| \ge \frac{200r}{\delta^2 p} - |L| \ge \frac{150r}{\delta^2 p}$, using the fact that $\delta$ is sufficiently small. Since $|\overline{S}| \ge \frac{n}{3}$, we have $p|Z\setminus L||\overline{S}| > p\cdot \frac{150r}{\delta^2 p} \cdot \frac{n}{3} \ge \frac{100n}{\delta^2}$. Thus by \ref{item:property 2}, we have
\begin{equation}\label{eqn:bound_ZL_Sbar}
e_G(Z\setminus L,\overline{S}) \le (1+\delta)p|Z\setminus L||\overline{S}|.
\end{equation}
Substituting~\eqref{eqn:bound_Z_V} and~\eqref{eqn:bound_ZL_Sbar} into~\eqref{eq:T minus A to S lower bound}, we obtain
\begin{align}
    e_G(Z,S_k) &> \alpha(1-\delta)p|Z|n  - \left(\tfrac{1}{2}+\delta\right)(1+\delta)p|Z\setminus L||\overline{S}| - \frac{p|L\cap Z||\overline{S}|}{5000}\nonumber \\
    &= p|Z|\left((1-\delta)\alpha n - \left(\tfrac{1}{2}+\delta\right)(1+\delta)|\overline{S}| \right) + p|L\cap Z||\overline{S}|\left(\left(\tfrac{1}{2}+\delta\right)(1+\delta) - \tfrac{1}{5000}\right) \nonumber \\
    &\ge p|Z|\left(\alpha n - \tfrac{1}{2}|\overline{S}| -3\delta n\right) + 0 \nonumber \\
    &= p|Z|\left(\alpha n - \tfrac{1}{2}n + \tfrac{1}{2}|S| -3\delta n\right).
 \label{eq:lower bound Z and S cup Z}
\end{align}
Note that $|S_k|\le |S'| + \frac{200r}{\delta^2 p} = |S| + 3|K| + \frac{200r}{\delta^2 p} \le |S| + \delta n$, using \ref{item:property K small} and \ref{item:parameter hierarchy}.
Note also that $p|Z||S_k|\ge p|Z||S| \ge  p\cdot \frac{200r}{\delta^2 p} \cdot |S| \ge \frac{100n}{\delta^2}$, where the last inequality uses the fact that $|S| \ge \frac{(1-\eps)n}{r}\ge \frac{n}{2r}$. Thus, using \ref{item:property 2}, we have 
\begin{equation}\label{eq:upper bound Z and S cup Z}
    e_G(Z,S_k) \le (1+\delta)p|Z||S_k|\le (1+\delta)p|Z|\left(|S| + \delta n\right) 
    \le p|Z|\left(|S| + 3\delta n\right).
\end{equation}
Combining \eqref{eq:lower bound Z and S cup Z} and \eqref{eq:upper bound Z and S cup Z}, we obtain 
\[
|S| + 3\delta n \;\; \ge \;\; \alpha n - \tfrac{1}{2}n + \tfrac{1}{2}|S| -3\delta n,
\]
which, upon rearranging, gives
\[
|S| \;\; \ge \;\; (2\alpha - 1) n -12\delta n,
\]
giving a contradiction to $|S| \le (1-\eps)(2\alpha - 1)n$ because $\delta$ is sufficiently small relative to $\eps$ and $r$. This finishes the proof of \ref{item:size_SminusA}.


Finally, we will prove \ref{item:Hall's condition}. We order the vertices of $T\setminus A$ as follows. For convenience, we define $T' \coloneqq (T \setminus A) \setminus K$. Let $y_1$ be a vertex of $T'$ such that $d_H(y_1, A\setminus K')$ is maximal. Suppose we have defined $y_1,y_2,\dots y_{i}$ for $1 \le i < |T'|$. We then define $y_{i+1}$ to be a vertex in $T'\setminus\{y_1,\ldots,y_{i}\}$ such that $d_H\big(y_{i+1}, (A\cup\{y_1,\ldots,y_{i}\})\setminus K'\big)$ is maximal. Finally, we let the final vertices in the ordering of $T\setminus A$ be the vertices in $(T \setminus A)\cap K$ in any order. We will show that \ref{item:Hall's condition} holds with respect to this ordering of the vertices in $T\setminus A$. Define $A_0 \coloneqq A$, and for every $i \in [|T\setminus A|]$, define $A_i \coloneqq A\cup\{y_1,\ldots,y_i\}$.

Now fix a set $Z \subseteq T\setminus A$. Our goal is therefore to show that $\left|\bigcup_{y_i \in Z} N_H(y_i) \cap A_{i-1} \right| \ge 2|Z|$.
We will divide $Z$ according to whether $y_i$ is in $K$ or not. By \ref{item:property of K'}, every $y \in K$ has two neighbours in $K'$ and these neighbours are distinct for distinct $y \in K$. Since $K' \subseteq T \setminus K \subseteq A_{i-1}$ for $i > |(T\setminus A)\setminus K|$, we therefore have 
\begin{equation}\label{eqn:Z_cap_K}
\left|\left(\bigcup_{y_i \in Z \cap K} N_H(y_i) \cap A_{i-1} \right)\cap K'\right| \ge 2|Z \cap K|.
\end{equation}

Next, we consider $Z \setminus K$. We first show that $d_H(y,T\setminus K') > \frac{np}{12000r}$ for all $y \in T'$ by splitting into cases according to whether $y$ is in $L$, recalling that $L = \left\{y \in V: \left(\tfrac{1}{2}+\delta\right)d_G(y,\overline{S})< \frac{p|\overline{S}|}{5000}\right\}$.

Consider $y \in T' \cap L $, so $(\tfrac{1}{2} + \delta)d_G(y,\overline{S}) < \frac{p|\overline{S}|}{5000}$ and $d_H(y) > \frac{pn}{5000}$ (the latter one follows by \ref{item:property K small}). For such $y$, using \eqref{eq:T minus A has high edges in T} and the fact that the fact that $|S| \ge \frac{(1-\eps)n}{r}\ge \frac{n}{2r}$, we have 
\begin{equation}
d_H(y,T) > d_H(y) - \frac{p|\overline{S}|}{5000} 
> \frac{pn}{5000} - \frac{p(n-|S|)}{5000}
\ge \frac{np}{10000r}.
\label{eq:lb_degree_L_to_T}
\end{equation}

Consider $y \in T'\setminus L $, so $(\tfrac{1}{2} + \delta)d_G(y,\overline{S}) \ge \frac{p|\overline{S}|}{5000}$ and $d_G(y)\ge d_H(y) > \frac{pn}{5000}$. For such $y$, using \eqref{eq:T minus A has high edges in T} and \ref{item:parameter hierarchy}, we have 
\begin{equation}
d_H(y,T) > \alpha d_G(y) - (\tfrac{1}{2} + \delta)d_G(y,\overline{S}) 
\ge \left(\alpha - \tfrac{1}{2} - \delta\right)d_G(y)
\ge \left(\frac{1}{2r} - \delta\right)d_G(y) \ge \frac{np}{11000r}.
\label{eq:lb_degree_T_minus_L_to_T}
\end{equation}
So by~\eqref{eq:lb_degree_L_to_T} and~\eqref{eq:lb_degree_T_minus_L_to_T}, we conclude that $d_H(y,T) > \frac{np}{11000r}$ for all $y \in T'$. Moreover, by \ref{item:property of K'}, we know that each $y \in V(H)$ has at most two neighbours in $K'$ and so for all $y \in T'$ we have
\begin{equation}\label{eq: lower bound to T minus K'}
    d_H(y,T\setminus K') > \frac{np}{11000r} - 2 > \frac{np}{12000r},
\end{equation}
where we use $np \ge \frac{\log{n}}{2}$ and the fact that $n$ is sufficiently large.

We will now show that for all $i \in [|T'|]$, we have $d_H\big(y_{i},A_{i-1}\setminus K' \big) \ge \frac{np}{24000r}$.
Suppose for contradiction that for some $i \in [|T'|]$, we have $d_H\big(y_{i},A_{i-1}\setminus K'\big) < \frac{np}{24000r}$. Then letting $B \coloneqq T' \setminus \{y_1,\ldots,y_{i-1}\}$, we have $d_H(y, A_{i-1}\setminus K') < \frac{np}{24000r}$ for every $y \in B$. Since $B \subseteq T'$, by~\eqref{eq: lower bound to T minus K'} we have $d_H(y,T\setminus K') > \frac{np}{12000r}$ for all $y \in B$. 
Therefore, for all $y \in B$, we have 
\begin{align*}
    d_H(y,B) = d_H(y,T'\setminus\{y_1,\ldots,y_{i-1}\}) 
    &= d_H(y,T\setminus K') - d_H(y, A_{i-1}\setminus K') \\
    &> \frac{np}{12000r} - \frac{np}{24000r} = \frac{np}{24000r}
\end{align*}
 From this, we conclude that 
 \begin{equation}\label{eqn:lower_bound_B}
 e_G(B) \ge e_H(B) > \frac{np}{48000r}|B|
 \end{equation}
 By~\ref{item:size_SminusA}, we know $|B|\le \frac{200r}{\delta^2 p}$. Thus, using \ref{item:property 3}, we have 
\begin{equation}\label{eqn:upper_bound_B}
 e_G(B)\le |B|(np)^{1/8}.
 \end{equation}
Since $n$ is sufficiently large and $np \ge \frac{\log{n}}{2}$, \eqref{eqn:lower_bound_B} and \eqref{eqn:upper_bound_B} give a contradiction. Therefore we must have for all $i \in [|T'|]$,
\begin{equation}\label{eq:lower_bound_degree_y_i}
     d_H\big(y_{i}, A_{i-1}\setminus K' \big) \ge \frac{np}{24000r}.
\end{equation}


We can now show that $\left|\left(\bigcup_{y_i \in Z \setminus K} N_H(y_i) \cap A_{i-1}\right)\setminus K'\right| \ge 2|Z \setminus K|$. Suppose for contradiction that this does not hold, i.e.~that $|\bigcup_{y_i \in Z \setminus K}  N_H(y_i) \cap (A_{i-1}\setminus K')| < 2|Z \setminus K|$. We have by~\eqref{eq:lower_bound_degree_y_i} that
\begin{align}\label{eq:lower bound on final contradiction}
e_G\left((Z \setminus K) \cup \left(\bigcup_{y_i \in Z \setminus K} N_H(y_i) \cap (A_{i-1}\setminus K')\right)\right) &\ge e_H\left((Z \setminus K) \cup \left(\bigcup_{y_i \in Z \setminus K} N_H(y_i) \cap (A_{i-1}\setminus K')\right)\right) \nonumber \\
&\ge \frac{1}{2} \sum_{y_i \in Z \setminus K}d_H\big(y_{i}, A_{i-1}\setminus K' \big) \nonumber \\
&\ge |Z \setminus K|\frac{np}{48000r}.
\end{align}
Since $Z \setminus K \subseteq T\setminus A$, we know by~\ref{item:size_SminusA} that $|Z \setminus K| \le \frac{200r}{\delta^2 p}$. Thus, by assumption, 
\[
\left|(Z \setminus K) \cup \left(\bigcup_{y_i \in Z \setminus K} N_H(y_i)\cap (A_{i-1}\setminus K')\right)\right| < |Z \setminus K| + 2|Z \setminus K| \le \frac{600r}{\delta^2 p}.
\]
Therefore, using~\ref{item:property 3} we have
\begin{align}\label{eq:upper bound on final contradiction}
e_G\left((Z \setminus K) \cup \left(\bigcup_{y_i \in Z \setminus K} N_H(y_i) \cap (A_{i-1}\setminus K')\right)\right) 
&\le \left|(Z \setminus K) \cup \left(\bigcup_{y_i \in Z \setminus K} N_H(y_i) \cap (A_{i-1}\setminus K')\right)\right|(np)^{1/8} \nonumber \\
&\le 3|Z \setminus K|(np)^{1/8}.
\end{align}
Now, \eqref{eq:lower bound on final contradiction} and \eqref{eq:upper bound on final contradiction} contradict each other since $n$ is sufficiently large and $np \ge \frac{\log{n}}{2}$. Therefore, our assumption must have been false, and we must, in fac,t have 
\[
    \left|\left(\bigcup_{y_i \in Z \setminus K } N_H(y_i) \cap A_{i-1}\right)\setminus K'\right| \ge 2|Z \setminus K|.
\]
Combining this with \eqref{eqn:Z_cap_K}, we can now conclude that
 \begin{align*}
 \left|\bigcup_{y_i \in Z} N_H(y_i) \cap A_{i-1} \right|  
 &= \left|\bigcup_{y_i \in Z \setminus K } (N_H(y_i) \cap A_{i-1})  \cup \bigcup_{y_i \in Z \cap K } (N_H(y_i) \cap A_{i-1})\right|
 \\
 &\ge \left|\Bigg(\bigcup_{y_i \in Z \setminus K } N_H(y_i) \cap A_{i-1}\Bigg)\setminus K'\right| +  \left|\Bigg(\bigcup_{y_i \in Z \cap K } N_H(y_i) \cap A_{i-1}\Bigg) \cap K'\right| \\
 &\ge 2|Z \setminus K| + 2|Z \cap K| = 2|Z|.
 \end{align*}
This establishes \ref{item:Hall's condition}, completing the proof of \Cref{thm:clean-up_main}.

